import { createHash } from "node:crypto";
import { mkdir, readFile, readdir, writeFile } from "node:fs/promises";
import path from "node:path";

const MODULE_ID = "fallout2d20-compendium";
const ROOT = process.cwd();
const sourceRoot = path.join(ROOT, "src", "packs");
const hashId = value => createHash("sha256").update(`aat:${value}`).digest("hex").slice(0, 16);
const slug = value => value.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "");
const html = value => `<p>${value}</p>`;

async function documentNamed(pack, name) {
  const directory = path.join(ROOT, "generated", "source-packs", "en", `${pack}.db`);
  for (const file of await readdir(directory)) {
    if (!file.endsWith(".json")) continue;
    const document = JSON.parse(await readFile(path.join(directory, file), "utf8"));
    if (document.name === name && !document._key?.startsWith("!tables.results!")) return document;
  }
  throw new Error(`Template not found: ${pack}/${name}`);
}

function localizedSource(definition, language) {
  const official = language === "fr" && definition.issue <= 2;
  const book = definition.issue === 5 ? "astoundingly_awesome_tales_1_5" : `astoundingly_awesome_tales_${definition.issue}`;
  return {
    language,
    edition: language === "en" ? `en-digital-${definition.issue === 7 ? 2026 : definition.issue >= 5 ? 2024 : 2023}` : official ? "fr-official-2024" : "fr-project-1.2.0",
    translation: language === "en" ? "original" : official ? "official" : "project",
    ...(language === "fr" ? { translatedFrom: definition.id, structuralBaseline: false, translationReviewed: true, diceSymbolsReviewed: true, errataReviewed: true } : {}),
    ...(definition.issue <= 4 ? { appearances: [{ book: "astoundingly_awesome_tales_1_5", language, edition: language === "en" ? "en-digital-2024" : "fr-project-1.2.0", translation: language === "en" ? "original" : "project", status: "identical", page: definition.collectionPage }] } : {})
  };
}

function sourceFlags(definition) {
  const book = definition.issue === 5 ? "astoundingly_awesome_tales_1_5" : `astoundingly_awesome_tales_${definition.issue}`;
  return {
    book,
    page: definition.page,
    errataReviewed: true,
    artworkReviewed: true,
    artworkStatus: "shared",
    artworkSource: `Owned official PDF cover: Astoundingly Awesome Tales Issue No. ${definition.issue}.`,
    artworkSharingGroup: `aat-${definition.issue}-official-cover`,
    artworkSharingJustification: "The official adventure cover identifies and represents this publication's reusable structured content."
  };
}

function token(name, image) {
  return { name, img: image, displayName: 20, actorLink: false, width: 1, height: 1, scale: 1, mirrorX: false, mirrorY: false, lockRotation: false, rotation: 0, alpha: 1, vision: false, dimSight: 0, brightSight: 0, dimLight: 0, brightLight: 0, sightAngle: 0, lightAngle: 0, lightAlpha: 0.25, lightAnimation: { speed: 5, intensity: 5 }, disposition: -1, displayBars: 50, bar1: { attribute: "health" }, bar2: { attribute: "" }, flags: {}, randomImg: false, tint: null, lightColor: null, x: null, y: null, elevation: null };
}

function ability(definition, actorId, index) {
  const id = hashId(`${actorId}:ability:${index}:${definition.en}`);
  return { _id: id, type: "special_ability", img: "icons/svg/aura.svg", effects: [], folder: null, sort: index * 100000, flags: {}, system: { description: "", favorite: false, source: "" }, ownership: { default: 0 } };
}

function skill(definition, actorId, index, template) {
  const item = structuredClone(template);
  item._id = hashId(`${actorId}:skill:${definition.en}`);
  item.name = "";
  item.flags = {};
  item.folder = null;
  item.sort = index * 100000;
  item.system.value = definition.value;
  item.system.tag = Boolean(definition.tag);
  item.system.defaultAttribute = definition.attribute;
  item.system.description = "";
  item.system.summary = "";
  return item;
}

function weapon(definition, actorId, index, template) {
  const item = structuredClone(template);
  item._id = hashId(`${actorId}:weapon:${index}:${definition.en}`);
  item.name = "";
  item.img = `modules/${MODULE_ID}/artwork/Astoundingly%20Awesome%20Tales/AAT%20${definition.issue}.webp`;
  item.flags = {};
  item.folder = null;
  item.sort = index * 100000;
  item.system.description = "";
  item.system.damage.rating = definition.damage;
  for (const key of Object.keys(item.system.damage.damageType)) item.system.damage.damageType[key] = definition.types?.includes(key) ?? false;
  for (const value of Object.values(item.system.damage.damageEffect)) value.value = false;
  for (const effect of definition.effects ?? []) if (item.system.damage.damageEffect[effect]) item.system.damage.damageEffect[effect].value = true;
  for (const value of Object.values(item.system.damage.weaponQuality)) value.value = false;
  for (const quality of definition.qualities ?? []) if (item.system.damage.weaponQuality[quality]) item.system.damage.weaponQuality[quality].value = true;
  item.system.range = definition.range ?? "close";
  item.system.fireRate = definition.fireRate ?? 0;
  item.system.weaponType = definition.weaponType ?? "unarmed";
  return item;
}

function actorSystem(definition, template) {
  const system = structuredClone(template.system);
  system.level = { value: definition.level, currentXP: definition.xp, nextLevelXP: 0 };
  system.health = { ...(system.health ?? {}), value: definition.hp, max: definition.hp, min: 0, mod: 0 };
  system.initiative = { ...(system.initiative ?? {}), value: definition.initiative };
  system.defense = { ...(system.defense ?? {}), value: definition.defense };
  system.resistance = Object.fromEntries(Object.entries(definition.dr).map(([key, locations]) => [key, { ...(system.resistance?.[key] ?? {}), value: 0, locations }]));
  system.source = definition.issue === 5 ? "astoundingly_awesome_tales_1_5" : `astoundingly_awesome_tales_${definition.issue}`;
  system.bodyType = definition.bodyType ?? "humanoid";
  system.immunities = { poison: definition.dr.poison === "Immune", radiation: definition.dr.radiation === "Immune" };
  if (definition.kind === "creature") {
    for (const key of ["body", "mind", "melee", "guns", "other"]) system[key] = { ...(system[key] ?? {}), value: definition[key] };
    system.powerLevel = definition.power;
  } else {
    for (const [key, value] of Object.entries(definition.attributes)) system.attributes[key] = { value };
    system.carryWeight = { ...(system.carryWeight ?? {}), base: definition.carry ?? (150 + 10 * definition.attributes.str), value: 0, mod: 0 };
    system.meleeDamage = { ...(system.meleeDamage ?? {}), value: definition.meleeBonus ?? 0 };
    system.luckPoints = definition.luck ?? null;
  }
  return system;
}

async function writeActor(definition, templates) {
  definition.abilities = (definition.abilities ?? []).flatMap(entry => entry === commonAbilities.radPoison ? [entry, commonAbilities.poison] : [entry]);
  if (definition.dr.radiation === "Immune" && !definition.abilities.some(entry => entry.en === "Immune to Radiation")) definition.abilities.push(commonAbilities.radPoison);
  if (definition.dr.poison === "Immune" && !definition.abilities.some(entry => entry.en === "Immune to Poison")) definition.abilities.push(commonAbilities.poison);
  definition.id ??= hashId(`actor:${definition.en}`);
  const image = `modules/${MODULE_ID}/artwork/Astoundingly%20Awesome%20Tales/AAT%20${definition.issue}.webp`;
  const base = definition.kind === "creature" ? templates.creature : templates.npc;
  const actor = structuredClone(base);
  actor._id = definition.id;
  actor._key = `!actors!${definition.id}`;
  actor.name = "";
  actor.img = image;
  actor.token = token(definition.en, image);
  actor.items = [];
  actor.effects = [];
  actor.folder = null;
  actor.flags = { [MODULE_ID]: { source: sourceFlags(definition) } };
  actor.system = actorSystem(definition, base);
  actor.$folder = `aat-${definition.issue}`;
  for (const [index, entry] of (definition.skills ?? []).entries()) actor.items.push(skill(entry, definition.id, index, templates.skill));
  for (const [index, attack] of (definition.attacks ?? []).entries()) actor.items.push(weapon({ ...attack, issue: definition.issue }, definition.id, index, templates.weapon));
  for (const [index, entry] of (definition.abilities ?? []).entries()) actor.items.push(ability(entry, definition.id, index));

  const file = `${slug(definition.en)}__${definition.id}.json`;
  await writeJson(path.join(sourceRoot, "canonical", "denizens.db", file), actor);
  for (const language of ["en", "fr"]) {
    const values = {
      "/name": definition[language], "/token/name": definition[language],
      "/system/biography": html(definition[`bio_${language}`]),
      "/system/origin": definition[`origin_${language}`],
      "/flags/fallout2d20-compendium/source/language": localizedSource(definition, language).language,
      "/flags/fallout2d20-compendium/source/edition": localizedSource(definition, language).edition,
      "/flags/fallout2d20-compendium/source/translation": localizedSource(definition, language).translation
    };
    if (language === "fr") Object.assign(values, {
      "/flags/fallout2d20-compendium/source/embeddedWeaponTextTranslationReviewed": true,
      "/flags/fallout2d20-compendium/source/embeddedMiscellanyTextTranslationReviewed": true,
      "/flags/fallout2d20-compendium/source/specialAbilityTextTranslationReviewed": true
    });
    if (language === "fr" && definition.kind === "npc") values["/system/carryWeight/base"] = actor.system.carryWeight.base / 2;
    const localized = localizedSource(definition, language);
    for (const [key, value] of Object.entries(localized)) if (!["language", "edition", "translation"].includes(key)) values[`/flags/fallout2d20-compendium/source/${key}`] = value;
    for (const [index, attack] of (definition.attacks ?? []).entries()) {
      const id = actor.items[(definition.skills?.length ?? 0) + index]._id;
      values[`/items/@${id}/name`] = attack[language];
      values[`/items/@${id}/system/description`] = html(attack[`text_${language}`]);
      if (language === "fr") values[`/items/@${id}/system/weight`] = 0;
    }
    for (const [index, entry] of (definition.abilities ?? []).entries()) {
      const id = actor.items[(definition.skills?.length ?? 0) + (definition.attacks?.length ?? 0) + index]._id;
      values[`/items/@${id}/name`] = entry[language];
      values[`/items/@${id}/system/description`] = html(entry[`text_${language}`]);
    }
    for (const [index, entry] of (definition.skills ?? []).entries()) values[`/items/@${actor.items[index]._id}/name`] = entry[language];
    const overlay = { _key: actor._key, _file: `${slug(definition[language])}__${definition.id}.json`, values };
    await writeJson(path.join(sourceRoot, "locales", language, "denizens.db", overlay._file), overlay);
  }
}

async function writeJson(file, value) {
  await mkdir(path.dirname(file), { recursive: true });
  await writeFile(file, `${JSON.stringify(value, null, 2)}\n`);
}

async function writeRootItem(definition, template) {
  definition.id ??= hashId(`item:${definition.pack}:${definition.en}`);
  const item = structuredClone(template);
  item._id = definition.id;
  item._key = `!items!${definition.id}`;
  item.name = "";
  item.img = `modules/${MODULE_ID}/artwork/Astoundingly%20Awesome%20Tales/AAT%20${definition.issue}.webp`;
  item.flags = { [MODULE_ID]: { source: sourceFlags(definition) } };
  item.folder = null;
  item.system.source = definition.issue === 5 ? "astoundingly_awesome_tales_1_5" : `astoundingly_awesome_tales_${definition.issue}`;
  item.system.description = "";
  if ("effect" in item.system) item.system.effect = "";
  Object.assign(item.system, definition.system);
  definition.apply?.(item.system);
  if (definition.pack === "weapons" && item.system.mods) item.system.mods.list = [];
  item.$folder = definition.folder;
  const canonicalFile = `${slug(definition.en)}__${definition.id}.json`;
  await writeJson(path.join(sourceRoot, "canonical", `${definition.pack}.db`, canonicalFile), item);
  for (const language of ["en", "fr"]) {
    const localized = localizedSource(definition, language);
    const values = {
      "/name": definition[language],
      "/system/description": html(definition[`description_${language}`]),
      "/flags/fallout2d20-compendium/source/language": localized.language,
      "/flags/fallout2d20-compendium/source/edition": localized.edition,
      "/flags/fallout2d20-compendium/source/translation": localized.translation
    };
    if (definition[`effect_${language}`] !== undefined) values["/system/effect"] = html(definition[`effect_${language}`]);
    if (language === "fr" && item.system.ammo === "Gamma Rounds") values["/system/ammo"] = "Cartouche Gamma";
    if (language === "fr" && typeof definition.system.weight === "number") values["/system/weight"] = definition.system.weight / 2;
    for (const [key, value] of Object.entries(localized)) if (!["language", "edition", "translation"].includes(key) && value !== undefined) values[`/flags/fallout2d20-compendium/source/${key}`] = value;
    const overlay = { _key: item._key, _file: `${slug(definition[language])}__${definition.id}.json`, values };
    await writeJson(path.join(sourceRoot, "locales", language, `${definition.pack}.db`, overlay._file), overlay);
  }
}

