const weaponApply = ({ damage, types, effects = [], qualities = [], range = "close", fireRate = 0, weaponType = "smallGuns", ammo = "" }) => system => {
  system.damage.rating = damage;
  for (const key of Object.keys(system.damage.damageType)) system.damage.damageType[key] = types.includes(key);
  for (const value of Object.values(system.damage.damageEffect)) value.value = 0;
  for (const effect of effects) if (system.damage.damageEffect[effect]) system.damage.damageEffect[effect].value = 1;
  for (const value of Object.values(system.damage.weaponQuality)) value.value = 0;
  for (const quality of qualities) if (system.damage.weaponQuality[quality]) system.damage.weaponQuality[quality].value = 1;
  system.range = range; system.fireRate = fireRate; system.weaponType = weaponType; system.ammo = ammo;
};

