async function writeTable({ en, fr, issue, page, collectionPage, folder, rows }) {
  const id = hashId(`table:${en}`);
  const results = rows.map((row, index) => ({ ...row, id: hashId(`table-result:${en}:${index}`) }));
  const table = { _id:id, _key:`!tables!${id}`, img:`modules/${MODULE_ID}/artwork/Astoundingly%20Awesome%20Tales/AAT%20${issue}.webp`, formula:"1d20", replacement:true, displayRoll:true, folder:null, results:results.map(row => ({_id:row.id,_key:`!tables.results!${id}.${row.id}`,type:"text",img:"icons/svg/d20-black.svg",weight:row.range[1]-row.range[0]+1,range:row.range,drawn:false})), flags:{[MODULE_ID]:{source:sourceFlags({issue,page,collectionPage})}}, $folder:folder };
  await writeJson(path.join(sourceRoot,"canonical","roll-tables.db",`${slug(en)}__${id}.json`),table);
  for (const language of ["en","fr"]) {
    const localized = localizedSource({issue,page,collectionPage},language);
    const values = { "/name":language === "en" ? en : fr, "/flags/fallout2d20-compendium/source/language":localized.language, "/flags/fallout2d20-compendium/source/edition":localized.edition, "/flags/fallout2d20-compendium/source/translation":localized.translation };
    for (const [key,value] of Object.entries(localized)) if (!["language","edition","translation"].includes(key) && value !== undefined) values[`/flags/fallout2d20-compendium/source/${key}`]=value;
    for (const row of results) values[`/results/@${row.id}/text`] = row[language];
    await writeJson(path.join(sourceRoot,"locales",language,"roll-tables.db",`${slug(language === "en" ? en : fr)}__${id}.json`),{_key:table._key,_file:`${slug(language === "en" ? en : fr)}__${id}.json`,values});
  }
}
