async function addReusedAppearances(name, appearances) {
  const document = await documentNamed("denizens",name);
  for (const language of ["en","fr"]) {
    const directory = path.join(sourceRoot,"locales",language,"denizens.db");
    for (const file of await readdir(directory)) {
      if (!file.endsWith(".json")) continue;
      const target = path.join(directory,file);
      const overlay = JSON.parse(await readFile(target,"utf8"));
      if (overlay._key !== document._key) continue;
      const previous = overlay.values?.["/flags/fallout2d20-compendium/source/appearances"] ?? [];
      const added = appearances.map(({issue,page}) => ({book:issue === 5 ? "astoundingly_awesome_tales_1_5" : `astoundingly_awesome_tales_${issue}`,language,edition:language === "en" ? `en-digital-${issue === 7 ? 2026 : issue >= 5 ? 2024 : 2023}` : issue <= 2 ? "fr-official-2024" : "fr-project-1.2.0",translation:language === "en" ? "original" : issue <= 2 ? "official" : "project",status:"identical",page}));
      const replacedBooks = new Set(added.map(entry => entry.book));
      overlay.values["/flags/fallout2d20-compendium/source/appearances"]=[...previous.filter(entry => !replacedBooks.has(entry.book)),...added].filter((entry,index,array)=>array.findIndex(other=>other.book===entry.book&&other.language===entry.language)===index);
      await writeJson(target,overlay);
      break;
    }
  }
}
