  ["Wastelander",[{issue:3,page:14},{issue:5,page:58}]],["Super Mutant",[{issue:3,page:14},{issue:5,page:58}]],
  ["Eyebot",[{issue:5,page:86}]],["Assaultron",[{issue:5,page:100}]],
  ["Mirelurk",[{issue:6,page:18}]],["Mirelurk Hunter",[{issue:6,page:18}]],
  ["Feral Ghoul",[{issue:7,page:15}]],["Bloatfly",[{issue:7,page:28}]],["Radroach",[{issue:7,page:28}]],["Mister Handy",[{issue:7,page:36}]]
